  const after = restsOn.find((rests) => rests.role === 'after');
  const deviating = restsOn.find((rests) => rests.role === 'deviating');

  return (
    <Shell language={language}>
      <article style="padding-block-start: 40px">
        {supersededBy && (
          <p class="notice">
