import assert from 'node:assert/strict';
import type { Case } from '../../registry.ts';
import type { ApiContext } from '../run.test.ts';
import type { FigureSummary, Page } from '../../../../src/shared/api.ts';

export default {
  title: 'GET /figures lists figures, and its cursor returns the next page without repeats',
  async run(api: ApiContext) {
    const all = await api.json<Page<FigureSummary>>('/api/v1/figures');
    assert.equal(all.items.length, 3);
    assert.equal(all.nextCursor, null, 'a page that fits carries no cursor');

    const summary = all.items.find((figure) => figure.id === api.seeded.figures.ilana);
    assert.ok(summary, 'the seeded figure is listed');
    assert.equal(summary.displayName, 'אילנה מורג־עציון');
    assert.equal(summary.statementCount, 6);
    assert.equal(summary.flaggedCount, 2, 'the light-rail contradiction and the housing shift');
    assert.ok(summary.topics.includes('רכבת קלה'));

    const first = await api.json<Page<FigureSummary>>('/api/v1/figures?limit=2');
    assert.equal(first.items.length, 2);
    assert.ok(first.nextCursor);
    const second = await api.json<Page<FigureSummary>>(`/api/v1/figures?limit=2&cursor=${encodeURIComponent(first.nextCursor!)}`);
    assert.equal(second.items.length, 1);
    const seen = [...first.items, ...second.items].map((figure) => figure.id);
    assert.equal(new Set(seen).size, seen.length, 'no figure appears on both pages');
    assert.deepEqual(seen.sort(), all.items.map((figure) => figure.id).sort(), 'and none is skipped between them');
  },
} satisfies Case<ApiContext>;
=== 5.2 ===
  async run(api: ApiContext) {
    const detail = await api.json<FigureDetail>(`/api/v1/figures/${encodeURIComponent(api.seeded.figures.ilana)}`);

    assert.equal(detail.figure.id, api.seeded.figures.ilana);
    assert.equal(detail.figure.role, 'חברת הכנסת (דמות לדוגמה)');
    assert.equal(detail.timeline.length, 6);

    const dated = detail.timeline.filter((entry) => entry.statement.saidAt !== undefined).map((entry) => entry.statement.saidAt!);
    assert.deepEqual(dated, [...dated].sort().reverse(), 'dated statements run newest to oldest');
    assert.equal(detail.timeline.at(-1)?.statement.id, api.seeded.statements.undatedCommittee,
      'a statement with no established date sorts after every dated one');

    const flagged = detail.timeline.filter((entry) => entry.flagged).map((entry) => entry.statement.id).sort();
    assert.deepEqual(flagged, [
      api.seeded.statements.housingBudget,
      api.seeded.statements.housingPermits,
      api.seeded.statements.lightRailDenial,
