11	    const early = await api.get('/api/v1/export/utterances.ndjson');
12	    assert.equal(early.status, 404);
13	    assert.equal(((await early.json()) as ErrorBody).error.code, 'no_export_yet');
14	
15	    // The real cron entry point of the real Worker writes it.
16	    await api.runScheduled();
17	
18	    const response = await api.get('/api/v1/export/utterances.ndjson');
19	    assert.equal(response.status, 200);
20	    assert.match(response.headers.get('content-type') ?? '', /application\/x-ndjson/);
21	
22	    const lines = (await response.text()).trim().split('\n');
23	    const records = lines.map((line) => JSON.parse(line));
24	    assert.equal(
25	      new Set(records.map((record) => record.utterance.id)).size,
26	      records.length,
27	      'one line per thing said — a line per document would put one speech in the file three times',
28	    );
29	
30	    const pledge = records.find((record) => record.utterance.id === api.seeded.utterances.lightRailPledge);
31	    assert.equal(pledge.figure.displayName, 'אילנה מורג־עציון');
32	    assert.deepEqual(pledge.utterance.saidAt, { value: '2024-03-12', precision: 'day' });
33	    // Every document that reported it is on the same line, so a researcher reading only
34	    // the export can still get to each one.
35	    assert.equal(pledge.attestations.length, 3);
36	    assert.equal(new Set(pledge.attestations.map((a: { source: { id: string } }) => a.source.id)).size, 3);
37	
38	    // A date established only to the month keeps its precision here too.
39	    const monthly = records.find((record) => record.utterance.id === api.seeded.utterances.rally);
40	    assert.deepEqual(monthly.utterance.saidAt, { value: '2025-04', precision: 'month' });
41	
42	    const undated = records.find((record) => record.utterance.id === api.seeded.utterances.undatedCommittee);
43	    assert.equal('saidAt' in undated.utterance, false, 'unknown stays unknown in the export too');
44	  },
45	} satisfies Case<ApiContext>;

